/*
 * vm.h -- Stage 1 custom stack machine (Phase 2 deliverable).
 *
 * INTERPRETER NOTES (internal; full ISA record in logs/PHASE_2_LOG.md):
 *   - 86 logical opcodes, GNU is not the only author: the opcode byte for a
 *     given logical opcode is a per-build assignment generated by
 *     vm_spec.py (see vm_tables.h); operand forms and operand endianness
 *     are per-build too.
 *   - 12 general-purpose 64-bit registers, a 256-entry value stack, a
 *     64-word data memory and a private *writable* code buffer (so the
 *     self-modifying opcodes CLOAD/CSTORE/CXOR/CADD/CREAD really do modify
 *     the running program image).
 *   - R7 is the "ledger" register: the ACC/ACCC/ACRM/ACCS family folds
 *     values into it. The Stage 2 key material is packed from R6, R7, R1
 *     and R2 once the trace has finished.
 *   - R10 is seeded by the host: 0 = ordinary run, 1 = debugger/automation
 *     detected. The embedded program branches on it and quietly perturbs
 *     the ledger, so a detected run still yields a well-formed but wrong
 *     key instead of an error.
 */
#ifndef CARTO_VM_H
#define CARTO_VM_H

#include <stdint.h>

#include "vm_tables.h"

typedef struct {
    uint64_t r[VM_NREG];
    uint64_t steps;
    int      fault;
} vm_result_t;

/* Run `prog` (len bytes) with R10 preset to (detect_flag & 1).
 * Returns 0 when the program halted normally, -1 on an invalid opcode. */
int vm_run(const unsigned char *prog, unsigned int len, int detect_flag,
           vm_result_t *out);

/* Stage 2 key material: LE64(r6) || LE64(r7) || LE64(r1) || LE64(r2). */
void vm_pack_key(const vm_result_t *res, unsigned char out[32]);

#endif /* CARTO_VM_H */